  /**
   * @method
   * @name luno#fetchOHLCV
   * @see https://www.luno.com/en/developers/api#tag/Market/operation/GetCandles
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} params extra parameters specific to the exchange API
   * endpoint
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
             std::any since = std::any{}, std::any limit = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("duration"),
                      this->safeValue(this->timeframes, timeframe, timeframe)},
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("since"),
                              this->parseToInt(since));
                 } else {
                   std::any duration = multiply(
                       multiply(1000, 1000), this->parseTimeframe(timeframe));
                   ::setValue(request, std::string("since"),
                              subtract(this->milliseconds(), duration));
                 }
                 std::any response = awaitValue(this->exchangePrivateGetCandles(
                     this->extend(request, params)));
                 //
                 //     {
                 //          "candles": [
                 //              {
                 //                  "timestamp": 1664055240000,
                 //                  "open": "19612.65",
                 //                  "close": "19612.65",
                 //                  "high": "19612.65",
                 //                  "low": "19612.65",
                 //                  "volume": "0.00"
                 //              },...
                 //          ],
                 //          "duration": 60,
                 //          "pair": "XBTEUR"
                 //     }
                 //
                 std::any ohlcvs = this->safeList(
                     response, std::string("candles"), ccxt::list{});
                 return this->parseOHLCVs(ohlcvs, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  std::any parseOHLCV(std::any ohlcv, std::any market = std::any{}) override {
    // {
    //     "timestamp": 1664055240000,
    //     "open": "19612.65",
    //     "close": "19612.65",
    //     "high": "19612.65",
    //     "low": "19612.65",
    //     "volume": "0.00"
    // }
    return ccxt::list{this->safeInteger(ohlcv, std::string("timestamp")),
                      this->safeNumber(ohlcv, std::string("open")),
                      this->safeNumber(ohlcv, std::string("high")),
                      this->safeNumber(ohlcv, std::string("low")),
                      this->safeNumber(ohlcv, std::string("close")),
                      this->safeNumber(ohlcv, std::string("volume"))};
  }

  /**
   * @method
   * @name luno#fetchMyTrades
   * @description fetch all trades made by the user
   * @see
   * https://www.luno.com/en/developers/api#tag/Orders/operation/ListUserTrades
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchMyTrades() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("since"), since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any response = awaitValue(
                     this->privateGetListtrades(this->extend(request, params)));
                 //
                 //      {
                 //          "trades":[
                 //              {
                 //                  "pair":"LTCXBT",
                 //                  "sequence":3256813,
                 //                  "order_id":"BXEX6XHHDT5EGW2",
                 //                  "type":"ASK",
                 //                  "timestamp":1648652135235,
                 //                  "price":"0.002786",
                 //                  "volume":"0.10",
                 //                  "base":"0.10",
                 //                  "counter":"0.0002786",
                 //                  "fee_base":"0.0001",
                 //                  "fee_counter":"0.00",
                 //                  "is_buy":false,
                 //                  "client_order_id":""
                 //              },...
                 //          ]
                 //      }
                 //
                 std::any trades = this->safeList(
                     response, std::string("trades"), ccxt::list{});
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

